create extension if not exists "pgcrypto";
create type public.app_role as enum ('admin','professional_staff','viewer');
create type public.player_status as enum ('active','injured','suspended','inactive');
create type public.match_status as enum ('draft','scheduled','postponed','cancelled','completed','missing_data');
create type public.squad_status as enum ('not_in_squad','unused_substitute','starter','substitute');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, email text not null unique, full_name text, role public.app_role not null default 'viewer', is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint no_extra_admin check (role <> 'admin' or lower(email) = 'noamfrostig@gmail.com'));
create table public.clubs (id uuid primary key default gen_random_uuid(), name text not null unique, short_name text not null, logo_url text, primary_color text not null default '#101064', secondary_color text not null default '#FFFFFF', created_at timestamptz not null default now());
create table public.seasons (id uuid primary key default gen_random_uuid(), name text not null unique, start_date date, end_date date, status text not null default 'preparation' check (status in ('preparation','active','completed','archived')), default_match_duration_minutes smallint not null default 90 check (default_match_duration_minutes > 0 and default_match_duration_minutes <= 180), created_at timestamptz not null default now());
create table public.teams (id uuid primary key default gen_random_uuid(), club_id uuid not null references public.clubs(id), name text not null, age_group text not null, league_name text not null, district text not null, current_season_id uuid references public.seasons(id), external_id text unique, external_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(club_id,name));
create table public.players (id uuid primary key default gen_random_uuid(), full_name text not null, birth_date date, dominant_foot text check (dominant_foot in ('right','left','both')), photo_url text, external_id text unique, external_url text, source text not null default 'manual', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.player_seasons (id uuid primary key default gen_random_uuid(), player_id uuid not null references public.players(id) on delete cascade, team_id uuid not null references public.teams(id) on delete cascade, season_id uuid not null references public.seasons(id) on delete restrict, shirt_number smallint check (shirt_number between 1 and 99), primary_position text not null, secondary_position text, squad_status public.player_status not null default 'active', previous_club text, joined_at date, professional_notes text, administrative_notes text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(player_id,team_id,season_id));
create table public.matches (id uuid primary key default gen_random_uuid(), team_id uuid not null references public.teams(id), season_id uuid not null references public.seasons(id), competition_name text not null, round_number smallint, opponent_name text not null, match_date date, kickoff_time time, home_or_away text not null check (home_or_away in ('home','away')), venue text, address text, team_score smallint check(team_score >= 0), opponent_score smallint check(opponent_score >= 0), match_status public.match_status not null default 'draft', external_id text unique, external_url text, source text not null default 'manual', professional_summary text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.match_player_stats (id uuid primary key default gen_random_uuid(), match_id uuid not null references public.matches(id) on delete cascade, player_season_id uuid not null references public.player_seasons(id) on delete cascade, squad_status public.squad_status not null, started boolean not null default false, entered_minute smallint check(entered_minute >= 0), exited_minute smallint check(exited_minute >= 0), minutes_played smallint not null default 0 check(minutes_played >= 0), goals smallint not null default 0 check(goals >= 0), assists smallint not null default 0 check(assists >= 0), yellow_cards smallint not null default 0 check(yellow_cards between 0 and 2), red_cards smallint not null default 0 check(red_cards between 0 and 1), position_played text, professional_notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(match_id,player_season_id));
create table public.goals (id uuid primary key default gen_random_uuid(), match_id uuid not null references public.matches(id) on delete cascade, scorer_player_season_id uuid references public.player_seasons(id), assisting_player_season_id uuid references public.player_seasons(id), minute smallint check(minute >= 0), is_own_goal boolean not null default false, is_penalty boolean not null default false, notes text, created_at timestamptz not null default now());
create table public.audit_logs (id uuid primary key default gen_random_uuid(), user_id uuid references public.profiles(id), action text not null, entity_type text not null, entity_id uuid, previous_data jsonb, new_data jsonb, created_at timestamptz not null default now());
create index on public.players(full_name); create index on public.matches(team_id, season_id, match_date); create index on public.match_player_stats(player_season_id); create index on public.audit_logs(created_at desc);
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end $$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.profiles where id = auth.uid() and lower(email) = 'noamfrostig@gmail.com' and role = 'admin' and is_active) $$;
create or replace function public.can_edit() returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.profiles where id = auth.uid() and role in ('admin','professional_staff') and is_active) $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles(id,email,full_name,role) values(new.id,lower(new.email),new.raw_user_meta_data->>'full_name',case when lower(new.email) = 'noamfrostig@gmail.com' then 'admin'::public.app_role else 'viewer'::public.app_role end); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create trigger profiles_updated before update on public.profiles for each row execute function public.set_updated_at(); create trigger teams_updated before update on public.teams for each row execute function public.set_updated_at(); create trigger players_updated before update on public.players for each row execute function public.set_updated_at(); create trigger player_seasons_updated before update on public.player_seasons for each row execute function public.set_updated_at(); create trigger matches_updated before update on public.matches for each row execute function public.set_updated_at(); create trigger match_stats_updated before update on public.match_player_stats for each row execute function public.set_updated_at();
create or replace view public.player_statistics with (security_invoker = true) as select ps.id player_season_id,p.full_name,count(mps.id)::int appearances,count(mps.id) filter(where mps.started)::int starts,coalesce(sum(mps.minutes_played),0)::int minutes,coalesce(sum(mps.goals),0)::int goals,coalesce(sum(mps.assists),0)::int assists from public.player_seasons ps join public.players p on p.id=ps.player_id left join public.match_player_stats mps on mps.player_season_id=ps.id group by ps.id,p.full_name;
alter table public.profiles enable row level security; alter table public.clubs enable row level security; alter table public.seasons enable row level security; alter table public.teams enable row level security; alter table public.players enable row level security; alter table public.player_seasons enable row level security; alter table public.matches enable row level security; alter table public.match_player_stats enable row level security; alter table public.goals enable row level security; alter table public.audit_logs enable row level security;
create policy "authenticated read" on public.clubs for select to authenticated using(true); create policy "authenticated read" on public.seasons for select to authenticated using(true); create policy "authenticated read" on public.teams for select to authenticated using(true); create policy "authenticated read" on public.players for select to authenticated using(true); create policy "authenticated read" on public.player_seasons for select to authenticated using(true); create policy "authenticated read" on public.matches for select to authenticated using(true); create policy "authenticated read" on public.match_player_stats for select to authenticated using(true); create policy "authenticated read" on public.goals for select to authenticated using(true);
create policy "own profile read" on public.profiles for select to authenticated using(id=auth.uid() or public.is_admin()); create policy "admin profile update" on public.profiles for update to authenticated using(public.is_admin()) with check(public.is_admin() and (role <> 'admin' or lower(email)='noamfrostig@gmail.com'));
create policy "staff writes club" on public.clubs for all to authenticated using(public.can_edit()) with check(public.can_edit()); create policy "admin season write" on public.seasons for all to authenticated using(public.is_admin()) with check(public.is_admin()); create policy "staff writes team" on public.teams for all to authenticated using(public.can_edit()) with check(public.can_edit()); create policy "staff writes players" on public.players for all to authenticated using(public.can_edit()) with check(public.can_edit()); create policy "staff writes player seasons" on public.player_seasons for all to authenticated using(public.can_edit()) with check(public.can_edit()); create policy "staff writes matches" on public.matches for all to authenticated using(public.can_edit()) with check(public.can_edit()); create policy "staff writes stats" on public.match_player_stats for all to authenticated using(public.can_edit()) with check(public.can_edit()); create policy "staff writes goals" on public.goals for all to authenticated using(public.can_edit()) with check(public.can_edit()); create policy "admin audit read" on public.audit_logs for select to authenticated using(public.is_admin());
insert into public.clubs(name,short_name,primary_color,secondary_color) values('מועדון חדש','מועדון','#0A2341','#FFFFFF');
insert into public.seasons(name,status) values('עונה חדשה','preparation');
